mod error { pub use logscan::LexError; }
#[path = "../old_token.rs"]
#[allow(dead_code)]
mod old;
use std::time::Instant;

struct Rng(u64);
impl Rng { fn next(&mut self) -> u64 { self.0 ^= self.0 << 13; self.0 ^= self.0 >> 7; self.0 ^= self.0 << 17; self.0 } }

fn same(line: &str) {
    let mut a = old::Tokens::new(line);
    let mut b = logscan::tokenize(line);
    for _ in 0..line.len() + 3 {
        let (x, y) = (a.next(), b.next());
        assert_eq!(x, y, "line {line:?}");
    }
}

fn main() {
    let alphabet: &[&str] = &["[", "]", "\"", "\\", "=", " ", "\t", "a", "b", "n", "t", "1", "é", "\\\"", "\\n", "\\x", "k=", "[ts]"];
    let mut rng = Rng(0x9E3779B97F4A7C15);
    let mut checked = 0u64;
    for _ in 0..3_000_000 {
        let len = (rng.next() % 14) as usize;
        let line: String = (0..len).map(|_| alphabet[(rng.next() % alphabet.len() as u64) as usize]).collect();
        same(&line);
        checked += 1;
    }
    // exhaustive over a small alphabet
    let small = [b'[', b']', b'"', b'\\', b'=', b' ', b'a', b'n'];
    for len in 0..=7u32 {
        for mut code in 0..(small.len() as u64).pow(len) {
            let mut s = Vec::new();
            for _ in 0..len { s.push(small[(code % 8) as usize]); code /= 8; }
            same(std::str::from_utf8(&s).unwrap());
            checked += 1;
        }
    }
    println!("differential: {checked} lines identical");

    let sample = [
        "[2024-05-01T12:00:00Z] level=info msg=\"disk 91% full\" user=ann retries= done",
        "[2024-05-01T12:00:01Z] level=warn msg=\"say \\\"hi\\\"\\n\" worker-3 ok\tpid=4411",
        "started worker-3 ok a=1\tb=2 path=/var/log/x.log",
        "a=\"open", "ok =bad later=1",
    ];
    let mut dump = String::new();
    while dump.len() < 200_000_000 { for l in sample { dump.push_str(l); dump.push('\n'); } }
    let lines: Vec<&str> = dump.lines().collect();
    for round in 0..5 {
        let t = Instant::now();
        let mut c = 0usize;
        for l in &lines { for tok in old::Tokens::new(l) { c += tok.is_ok() as usize; } }
        let old_t = t.elapsed();
        let t = Instant::now();
        let mut d = 0usize;
        for l in &lines { for tok in logscan::tokenize(l) { d += tok.is_ok() as usize; } }
        let new_t = t.elapsed();
        assert_eq!(c, d);
        println!("round {round}: old {:?}  new {:?}  ({} MB)", old_t, new_t, dump.len() / 1_000_000);
    }
}
EOF
